  settings_data_tools: { ar: "أدوات البيانات (للمالك فقط)", en: "Data tools (owner only)", de: "Datentools (nur Eigentümer)", fr: "Outils de données (propriétaire uniquement)" },
  settings_data_tools_desc:{ ar: "إجراءات استرجاع نادرة. استخدمها فقط إذا لاحظت قيوداً مفقودة.", en: "Rare recovery actions. Only use these if you notice missing journal entries.", de: "Seltene Wiederherstellungsaktionen. Nur verwenden, wenn fehlende Buchungen auffallen.", fr: "Actions de récupération rares. À utiliser uniquement en cas d'écritures manquantes." },
  settings_repair_title:{ ar: "إعادة ربط قيود اليومية المفقودة", en: "Re-pair missing journal entries", de: "Fehlende Buchungen neu verknüpfen", fr: "Reconstituer les écritures manquantes" },
  settings_repair_desc:{ ar: "تفحّص جميع المعاملات في مساحة العمل وتُنشئ قيد يومية متوازن لكل معاملة لا قيد لها. تكرار التشغيل آمن.", en: "Walks every transaction in this workspace and posts a balanced double-entry for any one missing its journal entry. Safe to re-run.", de: "Durchläuft jede Transaktion und bucht eine ausgeglichene Doppelbuchung für jede ohne Journaleintrag. Sicher mehrfach ausführbar.", fr: "Parcourt chaque transaction et enregistre une double écriture équilibrée pour celles sans écriture. Réexécution sûre." },
  settings_repair_counting:{ ar: "جارٍ حساب القيود المفقودة...", en: "Counting missing entries...", de: "Fehlende Buchungen werden gezählt...", fr: "Comptage des écritures manquantes..." },
  settings_repair_in_sync:{ ar: "كل شيء متزامن — لا توجد قيود مفقودة.", en: "Everything is in sync — no missing entries.", de: "Alles synchron — keine fehlenden Buchungen.", fr: "Tout est synchronisé — aucune écriture manquante." },
  settings_repair_count:{ ar: "{n} معاملة بدون قيد يومية.", en: "{n} transactions are missing journal entries.", de: "{n} Transaktionen fehlen Buchungen.", fr: "{n} transactions sans écriture." },
