  settings_bt_manufacturing:{ ar: "شركة تصنيع (تشمل تكلفة البضائع المباعة)", en: "Manufacturing company (includes cost of goods sold)", de: "Produktionsunternehmen (inkl. Wareneinsatzkosten)", fr: "Entreprise de fabrication (avec coût des marchandises)" },
